        uniffiCallStatus in
    uniffi_soundscape_core_fn_constructor_soundscapecore_new(
        FfiConverterString.lower(dataDirectory),
        FfiConverterString.lower(cachesDirectory),uniffiCallStatus
    )
}
    self.init(unsafeFromHandle: handle)
}

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_soundscape_core_fn_free_soundscapecore(handle, $0) }
    }

    
